const required=(v,l)=>{if(v==null||String(v).trim()==='')throw new TypeError(`${l} is required`);return String(v).trim()};
export function createWorkflowDefinition({id,initialState,states=[],transitions=[]}={}){id=required(id,'workflow id');initialState=required(initialState,'initialState');const normalized=[...new Set(states.map(String))];if(!normalized.includes(initialState))normalized.unshift(initialState);const tx=transitions.map((t,i)=>{const from=required(t?.from,`transition ${i} from`),to=required(t?.to,`transition ${i} to`);if(!normalized.includes(from)||!normalized.includes(to))throw new Error(`transition references unknown state: ${from} -> ${to}`);return Object.freeze({id:String(t.id??`${from}->${to}`),from,to,event:t.event==null?null:String(t.event),guard:typeof t.guard==='function'?t.guard:null,metadata:Object.freeze({...t.metadata})})});return Object.freeze({id,initialState,states:Object.freeze(normalized),transitions:Object.freeze(tx)})}
export function createWorkflowInstance({id,workflowId,state,data={},history=[]}={}){return Object.freeze({id:required(id,'instance id'),workflowId:required(workflowId,'workflowId'),state:required(state,'state'),data:Object.freeze({...data}),history:Object.freeze([...history])})}
export function listAvailableTransitions(definition,instance,{event=null,context={}}={}){if(instance.workflowId!==definition.id)throw new Error('workflow definition mismatch');return definition.transitions.filter(t=>t.from===instance.state&&(event==null||t.event===event)&&(!t.guard||t.guard({instance,context,transition:t})===true))}
export function canTransition(definition,instance,to,options={}){return listAvailableTransitions(definition,instance,options).some(t=>t.to===String(to))}
export function transitionWorkflow(definition,instance,to,{event=null,context={},actorId=null,at=new Date().toISOString(),patch={}}={}){const target=String(to);const transition=listAvailableTransitions(definition,instance,{event,context}).find(t=>t.to===target);if(!transition)throw new Error(`transition not allowed: ${instance.state} -> ${target}`);return createWorkflowInstance({...instance,state:target,data:{...instance.data,...patch},history:[...instance.history,{from:instance.state,to:target,event:transition.event,transitionId:transition.id,actorId,at:new Date(at).toISOString()}]})}
